const fs = await import('node:fs');
const inputPath = process.env.INPUT_PATH;
if (!inputPath) throw new Error('INPUT_PATH env var required');
await fs.promises.access(inputPath).catch(()=>{throw new Error('Input file not found')});
globalThis.inputPath = inputPath;

const { asyncBufferFromFile, parquetMetadataAsync } = await import('hyparquet');
const file = await asyncBufferFromFile(globalThis.inputPath);
const metadata = await parquetMetadataAsync(file);
if (!metadata || typeof metadata.num_rows === 'undefined') throw new Error('Metadata missing num_rows');
globalThis.rowCount = Number(metadata.num_rows);
